def _targeted_literature_candidate_requirement_crosswalk_blocker_synthesis_rows() -> list[dict[str, object]]:
    crosswalk_rows = (
        SELECTED_CCFT_EMPIRICAL_DISCRIMINATOR_BASELINE_COMPONENT_EQUATION_SOURCE_APPLICABILITY_OPEN_SYSTEM_DECOHERENCE_TARGETED_LITERATURE_REVIEW_EXPANSION_CANDIDATE_REQUIREMENT_CROSSWALK_ROWS
    )
    blocker_specs = [
        (
            "OSD-BLOCKER-REGIME-MISMATCH-v0",
            "regime_mismatch",
            (
                "targeted literature did not validate a physical regime "
                "match for the future open-system decoherence baseline slot"
            ),
        ),
        (
            "OSD-BLOCKER-PARAMETER-MAPPING-v0",
            "missing_parameter_mapping",
            (
                "targeted literature did not supply an adopted variable, "
                "unit, rate, timescale, or parameter map"
            ),
        ),
        (
            "OSD-BLOCKER-OBSERVABLE-BINDING-v0",
            "missing_observable_binding",
            (
                "targeted literature did not bind a candidate source quantity "
                "to the selected coherence-lifetime observable"
            ),
        ),
        (
            "OSD-BLOCKER-MESOSCOPIC-PLATFORM-FIT-v0",
            "missing_mesoscopic_platform_fit",
            (
                "targeted literature did not establish applicability to the "
                "selected controlled mesoscopic coherence platform"
            ),
        ),
        (
            "OSD-BLOCKER-MEASUREMENT-FEEDBACK-v0",
            "missing_measurement_feedback_handling",
            (
                "targeted literature did not separate open-system "
                "decoherence from measurement, back-action, and feedback"
            ),
        ),
        (
            "OSD-BLOCKER-THERMODYNAMIC-ACCOUNTING-v0",
            "missing_thermodynamic_accounting",
            (
                "targeted literature did not settle dissipation, bath, "
                "uncertainty, or thermodynamic boundary accounting"
            ),
        ),
        (
            "OSD-BLOCKER-RESIDUAL-FORMULA-CONNECTION-v0",
            "missing_residual_formula_connection",
            (
                "targeted literature did not connect a future decoherence "
                "quantity to the normalized residual formula"
            ),
        ),
        (
            "OSD-BLOCKER-DOMAIN-ASSUMPTION-MISMATCH-v0",
            "domain_assumption_mismatch",
            (
                "targeted literature did not expose enough assumptions, "
                "approximations, provenance, and limits for adoption review"
            ),
        ),
    ]
    rows = []
    for blocker_class_id, blocker_class, future_resolution_path_needed in blocker_specs:
        scoped_rows = [
            row for row in crosswalk_rows if row["targeted_blocker_class"] == blocker_class
        ]
        candidate_ids = sorted({str(row["candidate_source_id"]) for row in scoped_rows})
        requirement_ids = sorted({str(row["requirement_id"]) for row in scoped_rows})
        representative_rows = [str(row["crosswalk_id"]) for row in scoped_rows[:3]]
        rows.append(
            {
                "blocker_class_id": blocker_class_id,
                "blocker_class": blocker_class,
                "affected_candidate_count": len(candidate_ids),
                "affected_requirement_count": len(requirement_ids),
                "representative_rows": representative_rows,
                "prior_48_row_status": (
                    "same blocker class already unresolved in the prior "
                    "replacement-source 48-row blocker synthesis"
                ),
                "new_64_row_status": (
                    "targeted literature expansion rows remain unsatisfied "
                    "and blocking for source validation, equation import, "
                    "and tau_baseline construction"
                ),
                "whether_blocker_worsened_or_persisted": "persisted",
                "future_resolution_path_needed": future_resolution_path_needed,
                "nonclaim_boundary": (
                    "blocker synthesis only; no blocker fixed, no requirement "
                    "relaxed, no source validated, no equation imported, no "
                    "scoring or calculation started, and no tau_baseline "
                    "computed"
                ),
            }
        )
    return rows


